package com.mindflow.app.game

import kotlin.random.Random

/**
 * A small Latin-square puzzle (mini Sudoku). 4×4 with 2×2 boxes, or 6×6 with 2×3 boxes.
 * Generated by filling a valid grid, then removing cells while the solution stays unique.
 * 0 marks a blank cell.
 */
data class SudokuPuzzle(
    val size: Int,
    val boxRows: Int,
    val boxCols: Int,
    val solution: List<List<Int>>,
    val givens: List<List<Int>>
) {
    val boxCountCols: Int get() = size / boxCols
    fun isGiven(r: Int, c: Int): Boolean = givens[r][c] != 0
    val givenCount: Int get() = givens.sumOf { row -> row.count { it != 0 } }
}

object MiniSudoku {

    fun generate(difficulty: Int, rnd: Random): SudokuPuzzle {
        val d = difficulty.coerceIn(1, 5)
        val size = if (d <= 3) 4 else 6
        val boxRows = 2
        val boxCols = if (size == 4) 2 else 3

        val solution = solve(emptyGrid(size), size, boxRows, boxCols, rnd)
            ?: error("failed to build a valid grid")

        val givens = solution.map { it.toMutableList() }
        val targetGivens = if (size == 4) when (d) { 1 -> 10; 2 -> 8; else -> 6 }
                           else when (d) { 4 -> 22; else -> 18 }

        var givenCount = size * size
        val order = (0 until size).flatMap { r -> (0 until size).map { r to it } }.shuffled(rnd)
        for (cell in order) {
            if (givenCount <= targetGivens) break
            val backup = givens[cell.first][cell.second]
            givens[cell.first][cell.second] = 0
            if (countSolutions(givens, size, boxRows, boxCols, limit = 2) != 1) {
                givens[cell.first][cell.second] = backup
            } else {
                givenCount--
            }
        }

        return SudokuPuzzle(size, boxRows, boxCols, solution, givens.map { it.toList() })
    }

    private fun emptyGrid(size: Int) = List(size) { MutableList(size) { 0 } }

    /** Returns a completed valid grid, or null if none exists (randomised backtracking fill). */
    fun solve(grid: List<MutableList<Int>>, size: Int, boxRows: Int, boxCols: Int, rnd: Random): List<List<Int>>? {
        val r = grid.indexOfFirst { row -> row.contains(0) }
        if (r == -1) return grid.map { it.toList() }
        val c = grid[r].indexOfFirst { it == 0 }
        val candidates = (1..size).shuffled(rnd)
        for (v in candidates) {
            if (canPlace(grid, r, c, v, size, boxRows, boxCols)) {
                grid[r][c] = v
                val solved = solve(grid, size, boxRows, boxCols, rnd)
                if (solved != null) return solved
                grid[r][c] = 0
            }
        }
        return null
    }

    /** Counts solutions up to [limit]. */
    fun countSolutions(grid: List<MutableList<Int>>, size: Int, boxRows: Int, boxCols: Int, limit: Int): Int {
        val r = grid.indexOfFirst { row -> row.contains(0) }
        if (r == -1) return 1
        val c = grid[r].indexOfFirst { it == 0 }
        var count = 0
        for (v in 1..size) {
            if (canPlace(grid, r, c, v, size, boxRows, boxCols)) {
                grid[r][c] = v
                count += countSolutions(grid, size, boxRows, boxCols, limit - count)
                grid[r][c] = 0
                if (count >= limit) break
            }
        }
        return count
    }

    private fun canPlace(grid: List<List<Int>>, r: Int, c: Int, v: Int, size: Int, boxRows: Int, boxCols: Int): Boolean {
        for (i in 0 until size) {
            if (grid[r][i] == v) return false
            if (grid[i][c] == v) return false
        }
        val br = (r / boxRows) * boxRows
        val bc = (c / boxCols) * boxCols
        for (i in br until br + boxRows) for (j in bc until bc + boxCols) {
            if (grid[i][j] == v) return false
        }
        return true
    }

    /** True when the grid is complete and every row, column and box is a permutation of 1..size. */
    fun isSolved(grid: List<List<Int>>, p: SudokuPuzzle): Boolean {
        val n = p.size
        if (grid.size != n || grid.any { it.size != n }) return false
        val expected = (1..n).toSet()
        for (r in 0 until n) if (grid[r].toSet() != expected) return false
        for (c in 0 until n) if ((0 until n).map { grid[it][c] }.toSet() != expected) return false
        for (br in 0 until n / p.boxRows) for (bc in 0 until p.boxCountCols) {
            val box = mutableListOf<Int>()
            for (i in 0 until p.boxRows) for (j in 0 until p.boxCols) {
                box.add(grid[br * p.boxRows + i][bc * p.boxCols + j])
            }
            if (box.toSet() != expected) return false
        }
        return true
    }
}
